drop policy if exists authenticated_sessions_only on public.payment_intents; drop policy if exists deny_anonymous_users on public.payment_intents; drop policy if exists payment_intents_deny_anonymous on public.payment_intents; drop policy if exists payment_intents_finance_read on public.payment_intents; drop policy if exists authenticated_sessions_only on public.payment_provider_events; drop policy if exists payment_provider_events_deny_anonymous on public.payment_provider_events; drop policy if exists payment_provider_events_finance_read on public.payment_provider_events; create policy payment_intents_finance_read on public.payment_intents for select to authenticated using (exists (select 1 from public.user_memberships um where um.user_id=auth.uid() and um.tenant_id=payment_intents.tenant_id and um.status='ACTIVE' and upper(um.role) = any(array['OWNER','ADMIN','MANAGER','FINANCE','ACCOUNTANT','FINANCE_MANAGER']))); create policy payment_provider_events_finance_read on public.payment_provider_events for select to authenticated using (exists (select 1 from public.user_memberships m where m.user_id=auth.uid() and m.tenant_id=payment_provider_events.tenant_id and m.status='ACTIVE' and upper(m.role) = any(array['OWNER','ADMIN','FINANCE','ACCOUNTANT','FINANCE_MANAGER']))); revoke insert, update, delete on public.payment_intents from anon, authenticated; revoke insert, update, delete on public.payment_provider_events from anon, authenticated; grant select on public.payment_intents to authenticated; grant select on public.payment_provider_events to authenticated;
